pug:
table.row.brad-full.white-bg
    tr
        td.wrapper.last
            table.twelve.columns
                tr
                    td.pb44.pt44.plr30
                        p.middle-title.pb32 {{ text_1 }}
                        .third-block
                            .inside-padding
                                p.fat-text {{ text_2 }}
                        .fourth-block
                            .inside-padding
                                p.fat-text {{ text_3 }}
                        .h-8 &nbsp;
                        .first-block
                            .inside-padding
                                p.fat-text.mw-1 {{ text_4 }}
                        .second-block
                            .inside-padding
                                p.fat-text {{ text_5 }}
                        .h-8 &nbsp;
                        .fiveth-block
                            .inside-padding
                                p.fat-text {{ text_6 }}
                        .sixth-block
